base_files.inventory.py:
"""Render an inventory digest from immutable stock records."""

from collections import Counter


def normalize_item(record):
    """Return the fields consumed by the inventory digest."""
    return {
        "sku": str(record["sku"]).strip(),
        "warehouse": str(record["warehouse"]).strip(),
        "quantity": int(record["quantity"]),
    }


def group_stock(records):
    """Sum quantities by warehouse and SKU without mutating input."""
    totals = Counter()
    for record in records:
        item = normalize_item(record)
        totals[(item["warehouse"], item["sku"])] += item["quantity"]
    return totals


def render_rows(totals):
    """Return sorted, nonempty warehouse stock rows."""
    rows = []
    for (warehouse, sku), quantity in sorted(totals.items()):
        if quantity:
            rows.append({
                "warehouse": warehouse,
                "sku": sku,
                "quantity": quantity,
            })
    return rows


def build_digest(records):
    """Return the inventory rows and total visible quantity."""
    totals = group_stock(records)
    rows = render_rows(totals)
    return {"rows": rows, "quantity": sum(row["quantity"] for row in rows)}


def format_digest(digest):
    """Produce a deterministic tab-separated export."""
    lines = ["warehouse\tsku\tquantity"]
    for row in digest["rows"]:
        lines.append(
            f'{row["warehouse"]}\t{row["sku"]}\t{row["quantity"]}'
        )
    return "\n".join(lines) + "\n"


class DigestCommand:
    """Adapt the inventory source to the export interface."""

    def __init__(self, source):
        """Keep the caller-owned source for later reads."""
        self.source = source

    def run(self):
        """Read current records and return their export text."""
        records = self.source.read()
        return format_digest(build_digest(records))

