base_files.reports.py:
"""Serve tenant-owned report exports from a shared storage root."""

from pathlib import Path


class ReportRepository:
    """Resolve report metadata using the active database connection."""

    def __init__(self, database):
        """Bind a repository to the supplied database adapter."""
        self.database = database

    def lookup(self, tenant, report_id):
        """Fetch report metadata scoped to the authenticated tenant."""
        return self.database.get_report(tenant, report_id)


class ReportService:
    """Coordinate metadata, export storage, and download headers."""

    def __init__(self, repository, storage_root):
        """Initialize the repository and export storage root."""
        self.repository = repository
        self.storage_root = Path(storage_root).resolve()

    def metadata(self, tenant, report_id):
        """Load metadata for use by a download request."""
        return self.repository.lookup(tenant, report_id)

    def resolve_export(self, relative_name):
        """Resolve an export location, rejecting paths outside storage."""
        target = (self.storage_root / relative_name).resolve()
        if not target.is_relative_to(self.storage_root):
            raise PermissionError("export is outside storage")
        return target

    def replace_repository(self, repository):
        """Switch the metadata source during connection rotation."""
        self.repository = repository

    def download(self, tenant, report_id):
        """Read the selected export and return its content and headers."""
        metadata = self.metadata(tenant, report_id)
        target = self.resolve_export(metadata["path"])
        content = target.read_bytes()
        return {
            "body": content,
            "content_type": "text/csv",
            "filename": metadata["filename"],
        }


def download_response(service, session, report_id):
    """Resolve a report using the authenticated session's tenant."""
    if not session.get("tenant"):
        raise PermissionError("tenant session required")
    return service.download(session["tenant"], report_id)


def rotate_connection(service, database):
    """Replace the database adapter after a connection configuration change."""
    service.replace_repository(ReportRepository(database))

