base_files.audit.py:
"""Page through a stable, ordered list of audit events."""


def validate_page_size(page_size):
    """Reject page sizes outside the supported service range."""
    if not isinstance(page_size, int) or isinstance(page_size, bool):
        raise ValueError("page size must be an integer")
    if not 1 <= page_size <= 100:
        raise ValueError("page size must be between 1 and 100")


class AuditReader:
    """Read audit events through an injected repository."""

    def __init__(self, repository):
        """Retain the repository used for ordered event reads."""
        self.repository = repository

    def page(self, tenant, after_id=None, page_size=25):
        """Return events following a cursor and an optional next cursor."""
        validate_page_size(page_size)
        events = self.repository.events_for(tenant)
        eligible = []
        for event in events:
            if after_id is None or event["id"] > after_id:
                eligible.append(dict(event))
        selected = eligible[:page_size]
        next_cursor = None
        if len(eligible) > page_size:
            next_cursor = selected[-1]["id"]
        return {"events": selected, "next_cursor": next_cursor}


class AuditEndpoint:
    """Adapt authenticated requests to audit pages."""

    def __init__(self, reader):
        """Bind the endpoint to its audit reader."""
        self.reader = reader

    def get(self, session, query):
        """Validate request parameters and return a tenant-scoped page."""
        tenant = session.get("tenant")
        if not tenant:
            raise PermissionError("tenant session required")
        after_id = query.get("after_id")
        if after_id is not None:
            after_id = int(after_id)
        page_size = int(query.get("page_size", 25))
        return self.reader.page(tenant, after_id, page_size)


def export_page(endpoint, session, query):
    """Return one page as newline-separated audit messages."""
    page = endpoint.get(session, query)
    lines = [event["message"] for event in page["events"]]
    return {
        "body": "\n".join(lines),
        "next_cursor": page["next_cursor"],
    }

